WITH f AS (SELECT p.prosecdef,p.proconfig,pg_get_functiondef(p.oid) AS def,has_function_privilege('authenticated','public.admin_deactivate_customers_v1(uuid[])','EXECUTE') AS authenticated_can_execute FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.oid=to_regprocedure('public.admin_deactivate_customers_v1(uuid[])')), issues AS (SELECT 'RPC khong ton tai' AS issue WHERE NOT EXISTS(SELECT 1 FROM f) UNION ALL SELECT 'RPC khong phai SECURITY DEFINER' WHERE EXISTS(SELECT 1 FROM f WHERE NOT prosecdef) UNION ALL SELECT 'RPC thieu search_path an toan' WHERE EXISTS(SELECT 1 FROM f WHERE NOT(COALESCE(proconfig,ARRAY[]::text[])@>ARRAY['search_path=public, pg_temp'])) UNION ALL SELECT 'authenticated chua duoc goi RPC' WHERE EXISTS(SELECT 1 FROM f WHERE NOT authenticated_can_execute) UNION ALL SELECT 'RPC van chan ke hoach dang giao' WHERE EXISTS(SELECT 1 FROM f WHERE def~'v_open_plan_count\s*>\s*0\s+OR' OR def~'OR\s+v_open_plan_count\s*>\s*0') UNION ALL SELECT 'RPC khong con dem va giu ke hoach dang giao' WHERE EXISTS(SELECT 1 FROM f WHERE def!~'open_plan_count' OR def!~'Ke hoach dang giao')) SELECT issue FROM issues;
